import csv
import io
import unittest

from exporter import export_rows

class ExportTests(unittest.TestCase):
    def test_header(self):
        self.assertTrue(export_rows([]).startswith("customer_id,region"))

    def rows(self, data):
        return list(csv.reader(io.StringIO(export_rows(data))))

    def region_of(self, data, index=1):
        return self.rows(data)[index][1]

    def test_missing_region_key_renders_na(self):
        self.assertEqual(self.region_of([{"customer_id": "007", "region": "EU"},
                                         {"customer_id": "008"}]), "NA")

    def test_none_region_renders_na(self):
        self.assertEqual(self.region_of([{"customer_id": "007", "region": "EU"},
                                         {"customer_id": "008",
                                          "region": None}]), "NA")

    def test_empty_string_region_stays_empty(self):
        self.assertEqual(self.region_of([{"customer_id": "007", "region": "EU"},
                                         {"customer_id": "008",
                                          "region": ""}]), "")

    def test_present_region_unchanged(self):
        self.assertEqual(self.region_of([{"customer_id": "007", "region": "US"}]),
                         "US")
        self.assertEqual(self.region_of([{"customer_id": "007",
                                          "region": "EU-East"}]),
                         "EU-East")

    def test_customer_id_preserved_including_leading_zeros(self):
        data = [{"customer_id": "000123", "region": "EU"}]
        self.assertEqual(self.rows(data)[1][0], "000123")

    def test_na_is_literal_not_header_placeholder(self):
        raw = export_rows([{"customer_id": "007", "region": "EU"},
                           {"customer_id": "008"}])
        self.assertIn("\n008,NA", raw)

if __name__ == "__main__":
    unittest.main()

